#!/usr/bin/env node
/**
 * Regenerates the exemption lists from the spec repository:
 *
 *   src/grandfathered_v2_sidesteps.ts  from grandfathered-v2-sidesteps.txt (CYBERSPACE_V2.md section 6.16)
 *   src/grandfathered_v1_hops.ts       from grandfathered-v1-hops.txt       (CYBERSPACE_V2.md section 5.13)
 *
 *   node scripts/grandfathered.mjs [path to a cyberspace clone] [ref]
 *
 * Defaults: ../cyberspace and origin/master. Each list is read from the ref
 * with git show, never from the clone's working tree, and the header of each
 * generated file names the commit the ref resolved to. Fetch the clone first.
 */

import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'

const [repo = '../cyberspace', ref = 'origin/master'] = process.argv.slice(2)

const git = (...args) => execFileSync('git', ['-C', repo, ...args], { encoding: 'utf8' })
const commit = git('rev-parse', `${ref}^{commit}`).trim()

const LISTS = [
  {
    list: 'grandfathered-v2-sidesteps.txt',
    out: 'grandfathered_v2_sidesteps.ts',
    name: 'GRANDFATHERED_V2_SIDESTEPS',
    commitName: null,
    doc: `The version 2 sidesteps exempt under CYBERSPACE_V2.md section 6.16, by
 * event id: an event listed here carries no \`mn\` tag, and a verifier accepts
 * its Merkle roots and openings without re-checking them and checks
 * everything else. Commentary per line: pubkey, created_at, heights (x,y,z),
 * audit.`,
  },
  {
    list: 'grandfathered-v1-hops.txt',
    out: 'grandfathered_v1_hops.ts',
    name: 'GRANDFATHERED_V1_HOPS',
    commitName: 'GRANDFATHERED_V1_HOPS_COMMIT',
    doc: `The version 1 hops exempt under CYBERSPACE_V2.md section 5.13, by event
 * id: an event listed here MAY lack the \`mn\` and \`mp\` tags, a verifier
 * accepts its \`proof\` (the section 5.6 proof_hash) without recomputing it,
 * and checks everything else about it as for any other hop. The list is filled
 * from the final census at the cutover to residue openings; until then it is
 * empty and no version 1 hop is exempt. Commentary per line: pubkey,
 * created_at, heights (x,y,z), K, audit.`,
  },
]

for (const { list, out, name, commitName, doc } of LISTS) {
  const text = git('show', `${commit}:${list}`)

  // Sections 5.13 and 6.16: lines starting with # are comments; every other
  // non-empty line starts with a 64-character lowercase hex event id, and the
  // rest is commentary.
  const entries = []
  for (const line of text.split('\n')) {
    const trimmed = line.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const [id, ...rest] = trimmed.split(/\s+/)
    if (!/^[0-9a-f]{64}$/.test(id)) throw new Error(`${list}: not a 64-hex event id: ${trimmed}`)
    entries.push({ id, note: rest.join(' ') })
  }
  if (new Set(entries.map((e) => e.id)).size !== entries.length) throw new Error(`${list} lists an id twice`)

  const body = entries.length === 0
    ? `export const ${name}: ReadonlySet<string> = new Set<string>([])\n`
    : `export const ${name}: ReadonlySet<string> = new Set([\n${entries.map((e) => `  '${e.id}', // ${e.note}`).join('\n')}\n])\n`
  const commitExport = commitName
    ? `\n/** The arkin0x/cyberspace commit the list above was generated from. */\nexport const ${commitName} = '${commit}'\n`
    : ''
  const source = `/**
 * GENERATED by scripts/grandfathered.mjs. Do not edit by hand; rerun it.
 *
 * Source: arkin0x/cyberspace ${commit}, ${list}
 *
 * ${doc}
 */
${body}${commitExport}`
  writeFileSync(new URL(`../src/${out}`, import.meta.url), source)
  console.log(`${entries.length} ids from ${commit} -> src/${out}`)
}
